syntax:
using Base::Base;  // In the derived class, this inherits constructors from Base class
// Implementation notes: The compiler implicitly declares constructors in the derived class.
// For a base constructor like Base(int x = 0), the derived class gets:
// - Derived(int x)  // If no conflicts
// The compiler checks for equivalent user-declared constructors and omits duplicates.

code_example:
#include <iostream>

class Base {
public:
    Base(int x) { std::cout << "Base constructor called with " << x << std::endl; }
    Base() { std::cout << "Base default constructor" << std::endl; }  // Includes default constructor
};

class Derived : public Base {
public:
    using Base::Base;  // Inherit all constructors from Base
};

int main() {
    Derived d1;       // Calls inherited default constructor
    Derived d2(42);   // Calls inherited constructor with int parameter
    return 0;
}
